/* Product presentation and honest empty states. Fixture provenance belongs to the workbench. */
window.ProductSurface=(()=>{
 const {esc,icon,button:B,link:L,top,row,empty}=UI,prior={...Views.map};
 const fixture=ProductContext.fixture;
 const profileResult=()=>fixture&&ProductContext.scene==='profile-sample'?{id:'profile-graphic-fixture',version:'graphic-layout-v1',source:{kind:'layout-fixture',label:'图形布局夹具',description:'布局示意，不含测评读数'},scale:{min:0,max:1,unit:'图形位置'},values:Object.fromEntries(D.factors.map(f=>[f[0],f[2]]))}:null;
 const notes=s=>[...s.observations,...s.reportNotes].sort((a,b)=>(b.updatedAt||b.createdAt||'').localeCompare(a.updatedAt||a.createdAt||''));
 const noResult=(title='还没有可查看的报告')=>`${top('返回')}<h1 class="info-title">${title}</h1><p class="page-lead">完成测评后，可以在这里回看结果与依据。</p>${L('选择测评','home',{cls:'btn full space-24',after:'arrow'})}${L('查看我的记录','records',{cls:'textbtn full space-12'})}`;
 function radar(result){
  const xy=(i,v)=>{const a=-Math.PI/2+i*Math.PI*2/16;return [160+Math.cos(a)*v,160+Math.sin(a)*v];},point=(i,r)=>xy(i,r).join(',');
  return `<div class="profile-radar"><svg viewBox="0 0 320 320" aria-label="16个因子位置图。未提供读数的因子不绘制位置。" role="img">${[30,60,90,120].map(r=>`<polygon points="${D.factors.map((_,i)=>point(i,r)).join(' ')}" fill="none" stroke="var(--line)"/>`).join('')}${D.factors.map((f,i)=>`<line x1="160" y1="160" x2="${xy(i,120)[0]}" y2="${xy(i,120)[1]}" stroke="var(--line)"/>`).join('')}${D.factors.map((f,i)=>{const value=result.values[f[0]];if(value==null)return '';const r=(value-result.scale.min)/(result.scale.max-result.scale.min)*120,[x,y]=xy(i,r);return `<circle cx="${x}" cy="${y}" r="4" fill="var(--primary)"/>`;}).join('')}</svg>${D.factors.map((f,i)=>{const [x,y]=xy(i,143);return B(f[0],'nav',{cls:'radar-axis','data-route':'factor-detail','data-id':f[0],'aria-label':f[0]+' '+f[1]+'，查看详情',style:`left:${x/3.2}%;top:${y/3.2}%`});}).join('')}</div><p class="radar-guidance">点选字母或下方因子，查看具体含义。</p>`;
 }
 const areas=[['behavior','性格与行为'],['decisions','思考与选择'],['values','在意的事'],['assumptions','待检验的想法'],['emotions','情感与需要'],['family','家庭与边界'],['communication','沟通与互动'],['strengths','优势与代价']];
 const groups=[['traits','人格倾向'],['relationships','关系模式'],['observations','个人画像'],['completion','认识进度']];
 const relationshipDimensions=[['D1','金钱资源','金钱与资源怎样安排，让彼此更自在？'],['D2','时间陪伴','相处时间怎样分配，才能兼顾陪伴和各自生活？'],['D3','规划带领与关系秩序','谁来规划、怎样协商，什么安排更适合自己？'],['D4','成长与价值确认','希望怎样支持彼此成长，又怎样感到被认可？'],['D5','情绪支持','需要怎样被理解，自己能怎样回应情绪？'],['D7','风险兜底','遇到困难时，期待怎样共同面对？'],['D8','亲密节奏与承诺','靠近和承诺的节奏，怎样才适合自己？'],['D9','自由与空间','亲近之余，希望保留多少自主与独处？']];
 const facets=[['ability','能做到'],['willingness','愿意投入'],['need','自己需要'],['boundary','边界']];
 function graphFrame(s,type){return `<iframe class="profile-botanical-map" title="${{traits:'人格倾向图谱',relationships:'关系需求图谱',personal:'个人画像图谱',completion:'认识进度图谱'}[type]}" src="../review/relationship-map/index.html?embedded=1&map=${type}${type==='relationships'&&new URLSearchParams(location.search).get('relationship')==='crystal'?'&geometry=crystal':''}&theme=${encodeURIComponent(s.theme)}${s.reduced?'&still=1':''}" loading="lazy"></iframe>`;}
 let graphController=null;
 function bindGraph(C){graphController=C;}
 window.addEventListener('message',e=>{
  if(!graphController||e.origin!==location.origin||![...document.querySelectorAll('.profile-botanical-map')].some(f=>f.contentWindow===e.source))return;
  const m=e.data;if(!m||m.type!=='zhiyu-map-detail'||typeof m.title!=='string'||typeof m.description!=='string')return;
  const allowed={'factor-detail':D.factors.map(f=>f[0]),'relationship-detail':relationshipDimensions.map(d=>d[0]),'observation-area':areas.map(a=>a[0]),records:[],home:[]};
  const target=Object.hasOwn(allowed,m.route)&&(allowed[m.route].length===0||allowed[m.route].includes(m.id));
  graphController.show(m.title.slice(0,80),`<p class="small muted">${esc(String(m.branch||'').slice(0,80))}</p><p class="space-12">${esc(m.description.slice(0,600))}</p><p class="small muted space-16">这里解释节点含义，不代表已经形成你的个人结果。</p>${target?L(m.route==='home'?'查看测评':'查看这个角度',m.route,{cls:'btn full space-24',...(m.id?{'data-id':m.id}:{})}):''}`);
 });
 function observationMap(s){return `<p class="small muted space-12">从已有经历看线索。未记录的地方可以继续留白。</p><div class="observation-map">${areas.map(([id,name])=>{const count=notes(s).filter(n=>n.observationArea===id).length;return L(`<strong>${name}</strong><span>${count?count+' 条记录':'未记录'}</span>`, 'observation-area',{cls:'observation-area','data-id':id});}).join('')}</div>${L('查看全部观察','records',{cls:'textbtn full space-12','data-filter':'本人记录'})}`;}
 function groupPanel(s,group,result){if(group==='completion')return graphFrame(s,'completion');if(group==='observations')return graphFrame(s,'personal')+observationMap(s);if(group==='relationships')return graphFrame(s,'relationships')+relationshipPanel(s);if(group==='traits')return `${graphFrame(s,'traits')}${result?radar(result):`<div class="profile-unknown">${icon('explore')}<h3>还没有形成完整画像</h3><p>从一次测评或一条具体经历开始。</p>${L('补充自己的情况','journal',{cls:'btn full space-16',after:'arrow'})}</div>`}<details class="profile-factor-list" ${result?'open':''}><summary>16个因子 ${icon('chevron','sm')}</summary><div class="profile-factor-entries">${D.factors.map(f=>row(f[0]+' · '+f[1],result?.values[f[0]]!=null?`${result.values[f[0]].toFixed(2)} / ${result.scale.max} ${result.scale.unit}`:'还没有读数','factor-detail','bottle','',{'data-id':f[0]})).join('')}</div></details>`;
 return '';
 }
 function relationshipPanel(s){return `<div class="profile-unknown"><h3>还没有关系模式的测评结果</h3><p>从具体经历，分别看看能力、投入意愿、需要与边界。</p></div><details class="profile-text-list"><summary>查看全部关系角度 · 8 项</summary><div class="relationship-dimensions">${relationshipDimensions.map(([id,label])=>{const n=notes(s).filter(x=>x.relationshipDimension===id).length;return row(label,n?n+' 条本人补充':'还没有读数','relationship-detail','link','',{'data-id':id});}).join('')}</div></details>`;}
 function relationshipDetail(s,p){
  const dim=relationshipDimensions.find(d=>d[0]===p.id);if(!dim)return noResult('没有找到这个关系角度');
  const prompts=dim[0]==='D7'?{ability:'遇到困难时，我现在能提供哪些实际支持？',willingness:'我愿意共同承担到什么程度？',need:'什么情况下，我需要对方一起面对？',boundary:'哪些风险或代价，是我不能承受的？'}:{ability:'现在的条件下，我能提供什么？',willingness:'即使有能力，我愿意投入多少？',need:'什么样的回应，会让我感到被支持？',boundary:'哪些事需要先商量，哪些是我的底线？'};
  return `${top('我的关系模式')}<h1 class="info-title">${dim[1]}</h1><p class="page-lead">${dim[2]}</p><section class="relationship-facets" aria-label="四个关系角度"><p class="relationship-reading-note">尚无测评读数，先记下自己的经历与想法。</p>${facets.map(([id,label])=>{const own=notes(s).filter(n=>n.relationshipDimension===dim[0]&&n.relationshipFacet===id);return `<article><div class="facet-heading"><h2>${label}</h2>${L('补充','journal',{cls:'textbtn facet-record','data-kind':'relationship:'+dim[0]+':'+id,icon:'plus','aria-label':'补充'+label+'的情况'})}</div>${own.length?own.map(n=>row(n.title,n.text.slice(0,80),'journal','edit','',{'data-id':n.id})).join(''):`<p class="facet-prompt">${prompts[id]}</p>`}</article>`;}).join('')}</section><details class="relationship-discussion"><summary>${icon('chat')}<span>围绕这些角度聊聊</span>${icon('chevron','sm')}</summary><p class="small muted">选择这次想谈的角度，再补充具体经历。</p><div class="discussion-angles">${facets.map(([id,label])=>L(label,'assistant-chat',{cls:'btn secondary','data-kind':'relationship:'+dim[0]+':'+id})).join('')}${L('整体看看','assistant-chat',{cls:'textbtn','data-kind':'relationship:'+dim[0],after:'arrow'})}</div></details>`;
 }
 function observationArea(s,p){const area=areas.find(a=>a[0]===p.id);if(!area)return noResult('没有找到这个观察角度');const own=notes(s).filter(n=>n.observationArea===area[0]);return `${top('我的画像')}<h1 class="info-title">${area[1]}</h1><p class="page-lead">你写下的经历可以继续补充，也可以改变原来的理解。</p>${own.length?own.map(n=>row(n.title,n.text.slice(0,90),'journal','edit','',{'data-id':n.id})).join(''):empty('这个角度还没有记录','从一件具体的事开始，不必急着下结论。')}${L('补充我的情况','journal',{cls:'btn full space-24','data-kind':'observation:'+area[0],icon:'edit'})}`;}
 function profile(s){
  const result=profileResult(),group=groups.some(g=>g[0]===s.profileGroup)?s.profileGroup:'traits',own=notes(s),progress=s.sessions.filter(x=>fixture||x.kind!=='interaction-demo').map(x=>({x,total:Array.isArray(x.questionIds)?x.questionIds.length:fixture&&x.version==='demo-3-v1'?D.questions.length:null})).filter(x=>x.total>0);
  return `<header class="v3-title"><div><h1>我的画像</h1><p>把倾向、经历与变化放在一起看。</p></div></header><div class="profile-groups" role="group" aria-label="选择画像角度">${groups.map(([id,label])=>B(label,'profile-group',{cls:group===id?'selected':'','data-id':id,'aria-pressed':group===id})).join('')}</div><section class="profile-tendencies"><h2>${groups.find(g=>g[0]===group)[1]}</h2>${groupPanel(s,group,result)}</section><section class="profile-progress"><h2>测评进度</h2>${progress.length?progress.map(({x,total})=>{const count=Object.keys(x.answers||{}).length;return L(`<span><strong>${x.mode==='ai'?'AI 重置版':'16PF 原版'}</strong><small>${count} / ${total} 个回答</small></span><progress max="${total}" value="${count}" aria-label="已保存${count}个回答，共${total}题"></progress>${icon('chevron','sm')}`,x.status==='completed'&&x.resultId?'report':x.status==='completed'?'review':'question',{cls:'profile-progress-row','data-id':x.resultId||x.id});}).join(''):`<p class="small muted space-12">还没有正在进行的测评。</p>${L('查看测评','home',{cls:'textbtn',after:'arrow'})}`}</section>${own.length||group!=='traits'||s.memories.some(m=>m.status==='candidate')?`<section class="profile-clues"><div class="section-head"><h2>关于我的线索</h2>${L('全部记录','records',{cls:'textbtn'})}</div>${own.length?own.slice(0,3).map(n=>row(n.title,n.text.slice(0,70),n.kind==='topic-record'?'topic-workspace':'journal','edit','',{'data-id':n.id,...(n.topicId?{'data-topic':n.topicId}:{})})).join(''):`<p class="small muted">最近哪件事，让你留意到自己的需要或习惯？</p>`}${own.length||group!=='traits'?L('补充我的情况','journal',{cls:'btn secondary full space-16',icon:'plus'}):''}${s.memories.filter(m=>m.status==='candidate').length?row('待确认的内容',s.memories.filter(m=>m.status==='candidate').length+' 条','memories','memory'):''}</section>`:''}<div class="plain-list space-24">${row('与AI一起理解','带着具体经历继续整理','assistant-chat','chat')}${row('以前的对话','找回原来的问题与记录','conversations','clock')}</div>`;
 }
 function factor(s,p){const f=D.factors.find(x=>x[0]===p.id);if(!f)return noResult('没有找到这个因子');const result=profileResult(),value=result?.values[f[0]],own=notes(s).filter(n=>n.factorId===f[0]);return `${top('我的画像')}<span class="overline">${f[0]} · ${f[1]}</span><h1 class="info-title">${f[1]}</h1><p class="page-lead">${esc(f[4])}</p><section class="card space-24"><h2>${result?.source.kind==='layout-fixture'?'布局示意':'我的倾向'}</h2><p class="space-12">${value==null?'还没有这个角度的读数。':esc(value.toFixed(2)+' / '+result.scale.max+' '+result.scale.unit)}</p>${value==null?'':`<dl class="order-facts"><dt>来源</dt><dd>${esc(result.source.label)}</dd><dt>说明</dt><dd>${esc(result.source.description)}</dd></dl>`}</section><section class="space-24"><h2>可用依据</h2><p class="small muted space-12">${own.length?'有 '+own.length+' 条本人补充，可以回看当时的情境。':'还没有关联的经历。想一想，这个角度在不同场合是否相同？'}</p>${own.map(n=>row(n.title,n.text.slice(0,70),'journal','edit','',{'data-id':n.id})).join('')}</section>${L('补充我的情况','journal',{cls:'btn full space-24','data-kind':'factor:'+f[0],icon:'edit'})}${L('请AI帮我理解','assistant-chat',{cls:'btn secondary full space-12','data-kind':'factor:'+f[0],icon:'chat'})}`;}
 function chat(s,p){
  const selected=p.kind||s.assistantTopic||'',parts=selected.split(':'),factor=parts[0]==='factor'?D.factors.find(f=>f[0]===parts[1]):null,dim=parts[0]==='relationship'?relationshipDimensions.find(d=>d[0]===parts[1]):null,facet=facets.find(f=>f[0]===parts[2]);
  const label=factor?factor[1]:dim?dim[1]+(facet?' · '+facet[1]:''):'';
  return `${top('我的画像')}<h1 class="info-title">一起理清这件事</h1>${label?`<section class="chat-topic card space-16"><span class="small muted">这次想了解</span><h2>${esc(label)}</h2><p class="small muted space-8">${dim?esc(dim[2]):'结合具体经历，看看这个角度在不同情境下的变化。'}</p></section>`:''}${UI.composer(s.assistantDraft,s.assistantSources,s.logged)}<p class="small muted space-12">需要用到自己的记录时，由你选择资料。不会自动加入或发送。</p><div class="plain-list space-24">${row('以前的对话','回到原来的问题','conversations','clock')}${row('记住的内容','查看、修改或停用','memories','memory')}</div>`;
 }

 Views.map.assistant=profile;Views.map.portrait=profile;Views.map['factor-detail']=factor;Views.map['observation-area']=observationArea;Views.map['relationship-detail']=relationshipDetail;Views.map['assistant-chat']=chat;
 Views.map.report=(s,p)=>fixture?prior.report(s,p):noResult();
 Views.map.share=(s,p)=>fixture?prior.share(s,p):noResult('先选择一份可分享的报告');
 Views.map.question=(s,p)=>fixture||(p.id&&s.sessions.some(x=>x.id===p.id))?prior.question(s,p):`${top('认识')}<h1 class="info-title">暂时无法开始测评</h1><p class="page-lead">当前没有可用的题目。可以先选择一个生活问题，整理自己的情况。</p>${L('看看生活问题','explore',{cls:'btn full space-24'})}`;
 Views.map.auth=(s,p)=>`${top('返回')}<h1 class="info-title">登录</h1><p class="page-lead">账号服务暂不可用。已保存的本机记录不受影响。</p>${fixture?B('继续','demo-login',{cls:'btn full space-24'}):''}${L('回到我的记录','records',{cls:'btn secondary full space-24'})}`;
 Views.map.account=()=>`${top('我的')}<h1 class="info-title">账号与安全</h1><p class="page-lead">账号服务暂不可用。你可以查看或备份当前设备上的资料。</p>${L('我的数据','data',{cls:'btn full space-24'})}`;
 Views.map.membership=()=>`${top('返回')}<h1 class="info-title">会员服务</h1><p class="page-lead">暂时没有可购买的方案。</p>${L('查看已有订单','orders',{cls:'btn secondary full space-24'})}`;
 Views.map.checkout=()=>`${top('返回')}<h1 class="info-title">还没有可购买的方案</h1>${L('返回','membership',{cls:'btn secondary full space-24'})}`;
 Views.map.orders=(s,p)=>fixture?prior.orders(s,p):`${top('我的')}<h1 class="info-title">订单记录</h1>${empty('还没有订单','购买后，可以在这里查看订单和权益。')}`;
 Views.map.order=(s,p)=>fixture?prior.order(s,p):`${top('订单')}<h1 class="info-title">没有找到这笔订单</h1>${L('回到订单','orders',{cls:'btn secondary full space-24'})}`;
 Views.map.complete=(s,p)=>`${top('认识')}<h1 class="info-title">已保存这次作答</h1><p class="page-lead">可以回看当时的选择。</p>${L('回看作答','review',{cls:'btn full space-24','data-id':p.id||s.activeSession})}${L('回到认识','home',{cls:'btn secondary full space-12'})}`;
 Views.map.content=()=>`${top('我的数据')}<h1 class="info-title">可用内容</h1>${empty('暂时没有可用的测评题组','已保存的记录可以继续查看和修改。',L('我的记录','records',{cls:'btn secondary'}))}`;
 Views.map.support=()=>`${top('返回')}<h1 class="info-title">帮助与反馈</h1><div class="plain-list space-24">${row('保存遇到问题','保留输入并重试','','help','',{action:'save-help'})}${row('导出反馈','写下页面、问题和期望','','edit','',{action:'design-feedback'})}${row('我的数据','查看备份和导出范围','data','folder')}</div><p class="small muted space-24">反馈可下载为文本，暂不能直接提交。</p>`;
 Views.map.data=s=>`${top('我的')}<h1 class="info-title">我的数据</h1><p class="page-lead">资料保存在当前浏览器。导出一份备份，换设备时更容易找回。</p><div class="plain-list space-24">${row('导出资料','先选择要保留的范围','','download','',{action:'export-preview'})}${row('导入备份','检查文件后，由你确认导入','','upload','',{action:'v4-import'})}${row('导入范围','查看文件大小和已有内容限制','','info','',{action:'import-spec'})}${row('清理本机资料','先备份需要保留的内容','','trash','',{action:'clear-confirm'})}</div><p class="small muted space-24">备份文件未加密，请妥善保管。清理浏览器数据可能让未备份的记录无法找回。</p>`;
 Views.map.memories=s=>`${top('我的画像',L('引用设置','privacy',{cls:'textbtn'}))}<h1 class="info-title">记住的内容</h1><p class="page-lead">确认后再采用。你可以随时修改或停用。</p>${s.memories.length?s.memories.map(m=>`<article class="record-item space-16"><span class="pill">${{candidate:'待确认',active:'已确认',inactive:'已停用'}[m.status]||'待确认'}</span><h3>${esc(m.text)}</h3><div class="row wrap space-16">${m.status==='candidate'?B('确认采用','confirm-memory',{cls:'btn secondary','data-id':m.id}):m.status==='active'?B('停用','deactivate-memory',{cls:'btn secondary','data-id':m.id}):''}${B('修改','edit-memory',{cls:'textbtn','data-id':m.id})}${B('删除','delete-memory',{cls:'textbtn','data-id':m.id})}</div></article>`).join(''):empty('还没有确认的内容','从自己的具体经历开始，想留下的内容再确认。',L('写一条观察','journal',{cls:'btn secondary'}))}`;
 Views.map.privacy=s=>`${top('返回')}<h1 class="info-title">隐私与引用</h1><div class="plain-list space-24">${row('这次用到的资料','自己选择，也可以移除','','link','',{action:'context'})}${row('记住的内容','查看、修改或停用','memories','memory')}${row('本机资料','导出备份或按范围清理','data','folder')}</div><div class="switch-row"><span class="grow">保留后续对话<small>关闭后，新对话仅在当前窗口显示；已有对话不删除。</small></span>${B('<span></span>','toggle-chat-retention',{cls:'switch '+(s.chatRetention?'on':''),role:'switch','aria-checked':s.chatRetention,'aria-label':'保留后续对话'})}</div><div class="switch-row"><span class="grow">允许提出待确认内容<small>每一条仍由你确认，打开不会自动采用。</small></span>${B('<span></span>','toggle-memory',{cls:'switch '+(s.memoryEnabled?'on':''),role:'switch','aria-checked':s.memoryEnabled,'aria-label':'允许提出待确认内容'})}</div>`;
 Views.map.compare=()=>`${top('记录')}<h1 class="info-title">对照两次结果</h1>${empty('还没有可对照的两份结果','需要同一测量依据的结果，才能比较变化。',L('查看我的记录','records',{cls:'btn secondary'}))}`;
 const messages={
 'auth-spec':['登录','账号服务暂不可用。已保存的本机资料不受影响。'],
 'sync-spec':['备份与同步','当前资料保存在这个浏览器。可以先导出备份，云端同步暂不可用。'],
 'restore-spec':['恢复购买','暂时无法恢复购买。已有的本机记录仍可查看。'],
 'delete-account-spec':['注销账号','账号服务暂不可用。如需清理当前设备的资料，请前往“我的数据”。'],
 'recover-spec':['恢复账号','账号服务暂不可用。可以先查看本机资料并导出备份。'],
 'device-spec':['设备保护','可以使用设备提供的锁屏保护。此处暂不能单独设置解锁。'],
 'demo-boundary':['使用帮助','你可以整理自己的经历、保存观察、回看小尝试，并导出备份。'],
 'terms-spec':['使用条款','暂时无法读取条款。可以先返回查看自己的记录。'],
 'inactive-info':['停用之后','这条内容不再用于新的引用。已有对话和记录会保留。'],
 'refund-info':['退款进度','暂时无法获取退款进度。请保留原订单信息。'],
 'save-help':['先保留输入','保存失败时，请勿刷新或关闭页面。先重试；仍未成功时，可以导出临时内容或已有资料。'],
 'correct-response':['补充自己的情况','可以写下哪一点不适用，以及当时发生了什么。原来的对话会保留。']};
 function dispatch(action,el,C){const ds=el?.dataset||{};
  if(action==='profile-group'&&groups.some(g=>g[0]===ds.id)){if(C.commit(s=>s.profileGroup=ds.id)){C.repaint();document.querySelector('[data-action=profile-group][data-id='+ds.id+']')?.focus({preventScroll:true});}return true;}
  if(messages[action]){C.show(messages[action][0],'<p>'+messages[action][1]+'</p>');return true;}
  if(!fixture&&['demo-login','create-order','order-paid','order-active','refund','export-share'].includes(action)){C.show('暂时无法进行这个操作','<p>可以先返回，查看已有记录。</p>');return true;}
  if(action==='all-factors'){C.nav('single-factor');return true;}
  if(!fixture&&['source-report','quote-report','save-report-note'].includes(action)){C.nav('report');return true;}
  return false;
 }
 return {dispatch,profileResult,areas,groups,relationshipDimensions,facets,bindGraph};
})();
